import datetime
import math
from typing import Any, Dict, List, Optional, Tuple

import openpyxl
from openpyxl.utils.datetime import from_excel


SRC_PATH = "/root/Staffing_and_Shifts_Latest.xlsx"
OUT_PATH = "/root/additional_shift_blocks_needed_august_2025.xlsx"


def _norm_header(v: Any) -> str:
    if v is None:
        return ""
    return str(v).strip().lower().replace(" ", "_")


def to_date(v: Any, *, wb_epoch=None) -> Optional[datetime.date]:
    """Convert common excel-ish date representations into a datetime.date."""
    if v is None:
        return None

    if isinstance(v, datetime.datetime):
        return v.date()
    if isinstance(v, datetime.date):
        return v

    if isinstance(v, (int, float)):
        # Excel serial date; require epoch to interpret.
        if wb_epoch is None:
            return None
        try:
            dt = from_excel(v, wb_epoch)
            if isinstance(dt, datetime.datetime):
                return dt.date()
            if isinstance(dt, datetime.date):
                return dt
        except Exception:
            return None

    if isinstance(v, str):
        s = v.strip()
        if not s:
            return None
        # Common formats: ISO, or YYYY/MM/DD, or MM/DD/YYYY
        for fmt in (None, "%Y-%m-%d", "%Y/%m/%d", "%m/%d/%Y", "%d/%m/%Y"):
            try:
                if fmt is None:
                    # Python 3.11+: supports YYYY-MM-DD
                    return datetime.date.fromisoformat(s)
                return datetime.datetime.strptime(s, fmt).date()
            except Exception:
                pass
        return None

    return None


def to_iso(d: Optional[datetime.date]) -> Optional[str]:
    return d.isoformat() if d is not None else None


def find_header_row(ws, required_headers: List[str], *, scan_rows: int = 25) -> Tuple[int, Dict[str, int]]:
    """Find a header row and return (row_index, header->col_index)."""
    required_norm = [_norm_header(h) for h in required_headers]

    for r in range(1, min(ws.max_row, scan_rows) + 1):
        header_map: Dict[str, int] = {}
        for c in range(1, ws.max_column + 1):
            h = _norm_header(ws.cell(r, c).value)
            if h:
                header_map[h] = c
        if all(h in header_map for h in required_norm):
            return r, header_map

    raise ValueError(
        f"Could not find header row containing {required_headers} in sheet '{ws.title}'."
    )


def first_numeric_below_headers(ws) -> float:
    for r in range(1, ws.max_row + 1):
        for c in range(1, ws.max_column + 1):
            v = ws.cell(r, c).value
            if isinstance(v, (int, float)):
                return float(v)
    raise ValueError(f"Could not find numeric conversion ratio in sheet '{ws.title}'.")


def main() -> None:
    # 1) Read source workbook (no modifications)
    wb_src = openpyxl.load_workbook(SRC_PATH, data_only=True)

    ws_staff = wb_src["Current Staffing"]
    ws_incoming = wb_src["Incoming Shifts"]
    ws_ratio = wb_src["Ratio"]

    # AsOfDate from Current Staffing!B1, PlanningHorizonEnd from Current Staffing!D1
    as_of_raw = ws_staff.cell(1, 2).value
    end_raw = ws_staff.cell(1, 4).value

    as_of_date = to_date(as_of_raw, wb_epoch=wb_src.epoch)
    planning_end = to_date(end_raw, wb_epoch=wb_src.epoch)

    if as_of_date is None:
        raise ValueError(f"Could not parse AsOfDate from Current Staffing!B1: {as_of_raw!r}")
    if planning_end is None:
        raise ValueError(
            f"Could not parse PlanningHorizonEnd from Current Staffing!D1: {end_raw!r}"
        )

    remaining_days = (planning_end - as_of_date).days

    # Care unit list + relevant columns
    staff_header_row, staff_cols = find_header_row(
        ws_staff,
        ["Care_Unit", "Current_Staff_Hours", "Daily_Required_Hours"],
        scan_rows=25,
    )

    col_care = staff_cols[_norm_header("Care_Unit")]
    col_current = staff_cols[_norm_header("Current_Staff_Hours")]
    col_daily_req = staff_cols[_norm_header("Daily_Required_Hours")]

    care_units: List[Dict[str, Any]] = []
    for r in range(staff_header_row + 1, ws_staff.max_row + 1):
        name = ws_staff.cell(r, col_care).value
        if name is None or str(name).strip() == "":
            continue

        current_hours = ws_staff.cell(r, col_current).value
        daily_req = ws_staff.cell(r, col_daily_req).value

        # Keep numeric types if already numeric; otherwise coerce.
        current_hours = float(current_hours) if isinstance(current_hours, (int, float)) else 0.0
        daily_req = float(daily_req) if isinstance(daily_req, (int, float)) else 0.0

        care_units.append(
            {
                "Care_Unit": str(name).strip(),
                "Current_Staff_Hours": current_hours,
                "Daily_Required_Hours": daily_req,
            }
        )

    # Incoming shifts structure
    inc_header_row, inc_cols = find_header_row(
        ws_incoming,
        ["Care_Unit", "Shift Date"],
        scan_rows=25,
    )

    inc_care_col = inc_cols[_norm_header("Care_Unit")]
    inc_date_col = inc_cols[_norm_header("Shift Date")]

    # Prefer staff hours; fall back to other plausible hour columns if needed
    inc_hours_col = None
    for candidate in ("Staff Hours", "Staff_Hours", "Hours", "Quantity", "Inbound_Hours"):
        k = _norm_header(candidate)
        if k in inc_cols:
            inc_hours_col = inc_cols[k]
            break
    if inc_hours_col is None:
        raise ValueError(
            "Could not locate an incoming-hours column on 'Incoming Shifts' sheet. "
            "Expected a column like 'Staff Hours'."
        )

    incoming_rows: List[Dict[str, Any]] = []
    for r in range(inc_header_row + 1, ws_incoming.max_row + 1):
        cu = ws_incoming.cell(r, inc_care_col).value
        if cu is None or str(cu).strip() == "":
            continue
        d_raw = ws_incoming.cell(r, inc_date_col).value
        d = to_date(d_raw, wb_epoch=wb_src.epoch)

        hours_raw = ws_incoming.cell(r, inc_hours_col).value
        hours = float(hours_raw) if isinstance(hours_raw, (int, float)) else 0.0

        incoming_rows.append(
            {
                "Care_Unit": str(cu).strip(),
                "Shift_Date": d,
                "Staff_Hours": hours,
            }
        )

    # Ratio sheet: conversion ratio = Hours per shift block
    conversion_ratio = first_numeric_below_headers(ws_ratio)
    if conversion_ratio <= 0:
        raise ValueError(f"Invalid conversion ratio found in Ratio sheet: {conversion_ratio}")

    # 2) Compute results per unit
    unit_results: List[Dict[str, Any]] = []

    # pre-group incoming by care unit
    inc_by_unit: Dict[str, List[Dict[str, Any]]] = {}
    for row in incoming_rows:
        inc_by_unit.setdefault(row["Care_Unit"], []).append(row)

    for cu in care_units:
        name = cu["Care_Unit"]
        current_hours = cu["Current_Staff_Hours"]
        daily_req = cu["Daily_Required_Hours"]

        if daily_req > 0:
            current_coverage_days = current_hours / daily_req
            projected_understaff_date = as_of_date + datetime.timedelta(
                days=math.floor(current_coverage_days)
            )
        else:
            current_coverage_days = None
            projected_understaff_date = None

        incoming_for_unit = inc_by_unit.get(name, [])

        incoming_hours_by_end = 0.0
        earliest_scheduled = None
        for inc in incoming_for_unit:
            inc_date = inc["Shift_Date"]
            if inc_date is not None:
                if earliest_scheduled is None or inc_date < earliest_scheduled:
                    earliest_scheduled = inc_date
                if inc_date <= planning_end:
                    incoming_hours_by_end += inc["Staff_Hours"]

        if daily_req > 0:
            delivered_coverage_to_end = (current_hours + incoming_hours_by_end) / daily_req
        else:
            delivered_coverage_to_end = None

        remaining_demand_hours = daily_req * remaining_days

        additional_hours_needed = max(
            0.0, remaining_demand_hours - current_hours - incoming_hours_by_end
        )

        if additional_hours_needed > 0:
            shift_blocks_required = int(math.ceil(additional_hours_needed / conversion_ratio))
        else:
            shift_blocks_required = 0

        # Required_Shift_Start_Date logic
        required_shift_start_date = None
        if shift_blocks_required == 0:
            required_shift_start_date = None
        else:
            # Compare dates as date objects.
            if (
                earliest_scheduled is not None
                and projected_understaff_date is not None
                and earliest_scheduled <= projected_understaff_date
            ):
                if delivered_coverage_to_end is not None:
                    required_shift_start_date = as_of_date + datetime.timedelta(
                        days=math.floor(delivered_coverage_to_end)
                    )
                else:
                    required_shift_start_date = projected_understaff_date
            else:
                required_shift_start_date = projected_understaff_date

        rounding_applied = bool(
            additional_hours_needed > 0
            and (additional_hours_needed / conversion_ratio)
            != math.ceil(additional_hours_needed / conversion_ratio)
        )

        earlier_shift_required = bool(
            shift_blocks_required > 0
            and (
                earliest_scheduled is None
                or (
                    required_shift_start_date is not None
                    and required_shift_start_date < earliest_scheduled
                )
            )
        )

        unit_results.append(
            {
                "Care_Unit": name,
                "Current_Staff_Hours": current_hours,
                "Daily_Required_Hours": daily_req,
                "Current_Coverage_Days": current_coverage_days,
                "Projected_Understaff_Date": to_iso(projected_understaff_date),
                "Incoming_Hours_By_Aug31": incoming_hours_by_end,
                "Delivered_Coverage_To_Aug31": delivered_coverage_to_end,
                "Remaining_August_Demand_Hours": remaining_demand_hours,
                "Additional_Hours_Needed": additional_hours_needed,
                "Shift_Blocks_Required_Rounded_Up": shift_blocks_required,
                "Earliest_Scheduled_Shift_Date": to_iso(earliest_scheduled),
                "Required_Shift_Start_Date": to_iso(required_shift_start_date),
                "Rounding_Applied": rounding_applied,
                "Earlier_Shift_Required": earlier_shift_required,
            }
        )

    # 3) Build output workbook
    wb_out = openpyxl.Workbook()
    # Remove the default sheet
    default_ws = wb_out.active
    wb_out.remove(default_ws)

    ws_unit = wb_out.create_sheet("Unit_Results", 0)
    ws_addl = wb_out.create_sheet("Additional_Shifts_Needed", 1)

    # Unit_Results: metadata
    ws_unit["A1"] = "Field"
    ws_unit["B1"] = "Value"
    ws_unit["A2"] = "AsOfDate"
    ws_unit["B2"] = as_of_date.isoformat()
    ws_unit["A3"] = "PlanningHorizonEnd"
    ws_unit["B3"] = planning_end.isoformat()
    ws_unit["A4"] = "RemainingDaysInAugust"
    ws_unit["B4"] = int(remaining_days)

    unit_headers = [
        "Care_Unit",
        "Current_Staff_Hours",
        "Daily_Required_Hours",
        "Current_Coverage_Days",
        "Projected_Understaff_Date",
        "Incoming_Hours_By_Aug31",
        "Delivered_Coverage_To_Aug31",
        "Remaining_August_Demand_Hours",
        "Additional_Hours_Needed",
        "Shift_Blocks_Required_Rounded_Up",
        "Earliest_Scheduled_Shift_Date",
        "Required_Shift_Start_Date",
        "Rounding_Applied",
        "Earlier_Shift_Required",
    ]

    header_row_idx = 6
    for i, h in enumerate(unit_headers, start=1):
        ws_unit.cell(header_row_idx, i).value = h

    for idx, row in enumerate(unit_results, start=0):
        out_r = header_row_idx + 1 + idx
        for c_idx, h in enumerate(unit_headers, start=1):
            ws_unit.cell(out_r, c_idx).value = row.get(h)

    # Additional_Shifts_Needed
    addl_headers = [
        "Care_Unit",
        "Additional_Hours_Needed",
        "Shift_Blocks_Required_Rounded_Up",
        "Required_Shift_Start_Date",
        "Earliest_Scheduled_Shift_Date",
        "Earlier_Shift_Required",
    ]

    for i, h in enumerate(addl_headers, start=1):
        ws_addl.cell(1, i).value = h

    addl_row = 2
    for row in unit_results:
        if row["Shift_Blocks_Required_Rounded_Up"] and row["Shift_Blocks_Required_Rounded_Up"] > 0:
            for c_idx, h in enumerate(addl_headers, start=1):
                ws_addl.cell(addl_row, c_idx).value = row.get(h)
            addl_row += 1

    wb_out.save(OUT_PATH)

    # 4) Validate output (re-open and print required sections)
    wb_chk = openpyxl.load_workbook(OUT_PATH, data_only=True)
    print("Sheet names:", wb_chk.sheetnames)

    ws_u = wb_chk["Unit_Results"]
    ws_a = wb_chk["Additional_Shifts_Needed"]

    print("\nUnit_Results metadata A1:B4:")
    for r in range(1, 5):
        print([ws_u.cell(r, 1).value, ws_u.cell(r, 2).value])

    print("\nUnit_Results header row (row 6):")
    print([ws_u.cell(6, c).value for c in range(1, len(unit_headers) + 1)])

    print("\nUnit_Results data rows:")
    for r in range(7, 7 + len(unit_results)):
        print([ws_u.cell(r, c).value for c in range(1, len(unit_headers) + 1)])

    print("\nAdditional_Shifts_Needed header row (row 1):")
    print([ws_a.cell(1, c).value for c in range(1, len(addl_headers) + 1)])

    print("\nAdditional_Shifts_Needed data rows:")
    for r in range(2, ws_a.max_row + 1):
        print([ws_a.cell(r, c).value for c in range(1, len(addl_headers) + 1)])


if __name__ == "__main__":
    main()

